    "closureContext": "攤位收好了，會計帶走最後一份帳。韓梟把兩個杯子疊起來，又拆開。他的手機停在餐廳的訂位頁，上面沒有填任何人的名字。他說，有一件跟退款無關的事想問你，不是要你獎勵他把錢還了。你還沒回答，他先把手機放下了。今晚的邀請，你可以想清楚再回答。",
    "stalledContext": "會計寄來第二期補薪的確認信，韓梟看完，關掉正在看的改裝零件網頁。店員還是只跟他談工作，沒有約他下班吃飯。他有點不爽，也不想被誇成熟，只端出一杯新茶，問你味道怎麼樣。這杯茶他試了三個版本。你接過來，先聞了一下。",
    "ethicsContext": "合作的人要求，接下來的安排要先問過韓梟，由本人決定。你之前沒徵得同意就替人作主，大家仍對這件事不放心。",
