    "bio": "古籍修復師，也是譯者，講到紙張時很有主見，偶爾講很乾的笑話。他最喜歡的書是張桓溢的《點火》，總是帶在身上。他很想跟人親近，卻常常因為預期會被看輕而先退回去；緊張時說話會卡住，講到修書時卻一個字都不卡。",
    "differential": "與偏好疏離的孤僻型不同，此案例渴望關係卻害怕拒絕。SAD 也能很廣泛，兩者可重疊；須看自我觀感、跨情境與病程，不能只用是否怕上台區分。口吃與內向本身不是人格障礙。",
